 outcome,source,attempt,gap=notes[int(key)];a=o['source_url'].rsplit('/',1)[-1];results[key]={**o,'outcome':outcome,'review_depth':{'literal_statement':'read','historical':'fixed-ID/title scan; exact bounded matches in outputs/history-exact.txt; no earlier substantive route located','primary':'target and neighboring passages; details below; no whole-literature review','versions':versions[a],'version_receipts':'sources/*.receipt.json; outputs/version-review.json and old-version-labels.txt','formal':'not started; no full genuine literal endpoint proved'},'source_review':source,'mathematical_attempt_and_coverage':attempt,'precise_remaining_gap':gap,'credit_claimed':0,'root_review_required':True,'novelty_limit':'Bounded public searches only; no novelty clearance. Current Omega HEAD changed; full live tree request aborted at wall cap. No independent review requested by this investigator.'}
